// Dispatch0V_0 dispatches a typed variadic call to matching expectations.
func Dispatch0V_0[VA any](expects *[]*Call0V_0[VA], ctrl *Controller, receiver any, method string, va ...VA) {
	ctrl.T.Helper()
	ctrl.mu.Lock()
	start, step := 0, 1
	if ctrl.overridable {
		start, step = len(*expects)-1, -1
	}
	for idx := start; idx >= 0 && idx < len(*expects); idx += step {
		i, e := idx, (*expects)[idx]
		if len(e.varArgs) == 1 {
			if len(va) == 1 {
				if !e.varArgs[0].Matches(va[0]) {
					continue
				}
			} else if !e.varArgs[0].Matches(va) {
				continue
			}
		} else {
			if len(e.varArgs) != len(va) {
				continue
			}
			varMatch := true
			for j, vm := range e.varArgs {
				if !vm.Matches(va[j]) {
					varMatch = false
					break
				}
			}
			if !varMatch {
				continue
			}
		}
		if e.Call.exhausted() {
			continue
		}
		prereqOK := true
		for _, p := range e.Call.preReqs {
			if !p.satisfied() {
				prereqOK = false
				break
			}
		}
		if !prereqOK {
			continue
		}
		if ctrl.overridable {
			for j := 0; j < i; j++ {
				(*expects)[j].Call.minCalls = 0
			}
		}
		e.Call.numCalls++
		preReqs := e.Call.dropPrereqs()
		for _, p := range preReqs {
			ctrl.removeCall(p)
		}
		if e.Call.exhausted() {
			*expects = append((*expects)[:i], (*expects)[i+1:]...)
			ctrl.removeCall(e.Call)
		}
		ctrl.mu.Unlock()
		for _, f := range e.doFns {
			f(va...)
		}
		return
	}
	origin := callerInfo(2)
	ctrl.mu.Unlock()
	ctrl.T.Fatalf("Unexpected call to %T.%v(%v) at %s", receiver, method, va, origin)
}

